 12	/**
 13	 * Loads species configuration from an external properties file.
 14	 *
 15	 * @version 2022.03.02
 16	 */
 17	public final class SpeciesConfigurationLoader
 18	{
 19	    private static final String CONFIG_FILE = "organism-config.properties";
 20	    private static final EnumMap<Species, SpeciesConfig> CONFIGS = loadConfigs();
 21	
 22	    private SpeciesConfigurationLoader()
 23	    {
 24	    }
 25	
 26	    public static SpeciesConfig getConfig(Species species)
 27	    {
 28	        SpeciesConfig config = CONFIGS.get(species);
 29	        if(config == null) {
 30	            throw new IllegalStateException("Missing config for species " + species);
 31	        }
 32	        return config;
 33	    }
 34	
 35	    private static EnumMap<Species, SpeciesConfig> loadConfigs()
 36	    {
 37	        Properties properties = new Properties();
 38	        try (InputStream stream = openConfig()) {
 39	            properties.load(stream);
 40	        }
 41	        catch (IOException e) {
 42	            throw new IllegalStateException("Unable to load " + CONFIG_FILE, e);
 43	        }
 44	
 45	        EnumMap<Species, SpeciesConfig> configs = new EnumMap<>(Species.class);
 46	        for(Species species : Species.values()) {
 47	            configs.put(species, loadSpeciesConfig(species, properties));
 48	        }
 49	        return configs;
 50	    }
 51	
 52	    private static InputStream openConfig() throws IOException
 53	    {
 54	        InputStream classpathStream =
 55	            SpeciesConfigurationLoader.class.getResourceAsStream("/" + CONFIG_FILE);
 56	        if(classpathStream != null) {
 57	            return classpathStream;
 58	        }
 59	
 60	        Path path = Paths.get(CONFIG_FILE);
 61	        if(Files.exists(path)) {
 62	            return Files.newInputStream(path);
 63	        }
 64	
 65	        throw new IOException("Configuration file not found: " + CONFIG_FILE);
 66	    }
 67	
 68	    private static SpeciesConfig loadSpeciesConfig(Species species, Properties properties)
 69	    {
 70	        String prefix = species.getConfigKey() + ".";
 71	        boolean diurnal = readBoolean(properties, prefix + "diurnal");
 72	        int breedingAge = readInt(properties, prefix + "breedingAge");
 73	        int maxAge = readInt(properties, prefix + "maxAge");
 74	        double breedingProbability = readDouble(properties, prefix + "breedingProbability");
 75	        int maxLitterSize = readInt(properties, prefix + "maxLitterSize");
 76	        double creationProbability = readDouble(properties, prefix + "creationProbability");
 77	        Integer maxHealth = readOptionalInt(properties, prefix + "maxHealth");
 78	        Set<Species> foodSources = readSpeciesSet(properties, prefix + "foodSources");
 79	
 80	        return new SpeciesConfig(diurnal, breedingAge, maxAge,
 81	                                 breedingProbability, maxLitterSize,
 82	                                 creationProbability,
 83	                                 maxHealth, foodSources);
 84	    }
 85	
 86	    private static boolean readBoolean(Properties properties, String key)
 87	    {
 88	        return Boolean.parseBoolean(readRequired(properties, key));
 89	    }
 90	
 91	    private static int readInt(Properties properties, String key)
 92	    {
 93	        return Integer.parseInt(readRequired(properties, key));
 94	    }
 95	
 96	    private static Integer readOptionalInt(Properties properties, String key)
 97	    {
 98	        String value = properties.getProperty(key);
 99	        if(value == null || value.trim().length() == 0) {
100	            return null;
101	        }
102	        return Integer.valueOf(Integer.parseInt(value.trim()));
103	    }
104	
105	    private static double readDouble(Properties properties, String key)
106	    {
107	        return Double.parseDouble(readRequired(properties, key));
108	    }
109	
110	    private static Set<Species> readSpeciesSet(Properties properties, String key)
111	    {
112	        String value = properties.getProperty(key);
113	        if(value == null || value.trim().length() == 0) {
114	            return Collections.emptySet();
115	        }
116	
117	        Set<Species> speciesSet = new LinkedHashSet<>();
118	        String[] values = value.split(",");
119	        for(String item : values) {
120	            speciesSet.add(Species.valueOf(item.trim().toUpperCase()));
121	        }
122	        return speciesSet;
123	    }
124	
125	    private static String readRequired(Properties properties, String key)
126	    {
127	        String value = properties.getProperty(key);
128	        if(value == null) {
129	            throw new IllegalStateException("Missing required config key: " + key);
130	        }
131	        return value.trim();
132	    }
133	}
